(() => {
 const M=CVA,L=CVA_LESSONS,{m,n,pct,slider,select,bars,green,amber}=CVA_UI;
 L.push({id:'netting',name:'Exposure and netting',stage:'01 · Exposure and valuation',title:'What are you owed when positions are combined?',intro:'Exposure is the positive amount owed to you. Netting changes whether positive and negative trade values can offset before that positive part is taken.',chart:'Gross and net exposure in one market state',inputs:[slider('a','Trade A market value',-50,50,1,25),slider('b','Trade B market value',-50,50,1,-20),select('net','Enforceable netting arrangement',[['yes','Same recognised netting set'],['no','Separate netting sets']],'yes')],challenge:'Make one trade positive and the other negative. Now remove the netting agreement.',formula:'Same netting set: E = max(VA + VB, 0)\nSeparate sets: E = max(VA, 0) + max(VB, 0)',key:'Netting occurs within recognised sets. Expected positive exposure averages the resulting positive exposure over future states.',simpleTitle:'A payment you owe is not always a claim you can offset',simple:'Economic offsets between two trades do not establish a legal right to close them out together. The netting set determines where values can be combined before calculating positive exposure.',scope:'Two trades with one counterparty at one future state, without collateral. This illustrates the positive-part operation, not a full simulated exposure profile or enforceability assessment.',pages:[[406,'5.9–5.12 · collateral and netting'],[407,'5.13 · transaction and netting-set controls']],compute(s){const gross=Math.max(s.a,0)+Math.max(s.b,0),net=Math.max(s.a+s.b,0),e=s.net==='yes'?net:gross;return {stats:[['Selected exposure',m(e)],['Separate-set exposure',m(gross)],['Netting benefit',m(gross-e)]],bars:bars(['Trade A','Trade B','Separate sets','Selected exposure'],[s.a,s.b,gross,e]),headers:['Step','Value','Interpretation'],rows:[['Trade A',m(s.a),'Signed market value'],['Trade B',m(s.b),'Signed market value'],['Sum of positive parts',m(gross),'Separate netting sets'],['Positive part of sum',m(net),'One recognised netting set'],['Selected exposure',m(e),'Input to future exposure modelling']],explanation:`Exposure is ${m(e)} under the selected arrangement. ${s.net==='yes'?'Values offset before taking the positive part.':'A payable in one set does not offset a receivable in the other.'} The same calculation must be performed along the future exposure paths.`,note:'A negative trade value is an amount owed by the firm; it is not negative counterparty exposure in this unilateral example.'};}});
 L.push({id:'collateral',name:'Collateral and margin period',stage:'01 · Exposure and valuation',title:'Margin reduces exposure, but time leaves a gap',intro:'The margin period of risk covers the interval in which exposure can change before close-out or replacement. A margined trade can therefore retain CVA risk.',chart:'Positive exposure after a margin-period shock',inputs:[slider('mtm','Current net value',0,30,1,10),slider('threshold','Margin threshold',0,20,1,2),slider('daily','Daily value-change standard deviation',0,3,.1,1),slider('days','Re-margining interval N',1,10,1,1,'business days'),select('type','Transaction category',[['derivative','Derivative'],['sft','Securities financing transaction']],'derivative')],challenge:'Use a zero threshold and daily margin. Why can expected residual exposure still be positive?',formula:'Minimum MPOR: derivatives = 9 + N; SFTs = 4 + N (daily / intraday SFT margin: 5 days)\nToy residual exposure = max(current value + shock − collateral, 0)',key:'MPOR minima are prescribed in 5.9(3). The normal-shock exposure calculation is a teaching assumption.',simpleTitle:'A margin call cannot protect a period that has not happened yet',simple:'Collateral may cover the current position, while market moves after the last exchange create a new receivable. Thresholds and the time required to close out leave residual exposure.',scope:'Recognised cash collateral C = max(current value − threshold, 0), frozen through MPOR. The shock is normal with standard deviation daily input × √MPOR. No minimum transfer amount, initial margin, collateral volatility or dispute dynamics are modelled.',pages:[[405,'5.9 · collateral recognition'],[406,'5.9(3) · margin features and MPOR']],notes:[['Real collateral modelling','Recognition requires the collateral-management requirements and binding, legally enforceable documentation supported by legal review. Model the agreement’s unilateral/bilateral terms, margin frequency, thresholds, independent amounts, initial margins and minimum transfer amounts.']],compute(s){const days=(s.type==='sft'?4:9)+s.days,collateral=Math.max(s.mtm-s.threshold,0),mean=s.mtm-collateral,sd=s.daily*Math.sqrt(days),ee=M.positiveNormal(mean,sd),points=Array.from({length:81},(_,i)=>{const z=-4+i/10;return[z,Math.max(mean+sd*z,0)]});return {stats:[['Minimum MPOR',days+' days'],['Collateral assumed',m(collateral)],['Toy expected exposure',m(ee)]],series:[{name:'Residual positive exposure',color:green,data:points}],xlabel:'Standardised market shock (z)',headers:['Input or calculation','Result','Role'],rows:[['Recognised collateral',m(collateral),'Current value above threshold'],['Prescribed minimum MPOR',days+' business days',s.type==='sft'?'4 + N; daily case = 5':'9 + N'],['Shock standard deviation',m(sd),'Daily standard deviation × √MPOR'],['Residual mean before positive part',m(mean),'Current value − collateral'],['Expected positive residual',m(ee),'Normal-distribution teaching calculation']],explanation:`The prescribed minimum MPOR is ${days} business days. With ${m(collateral)} collateral frozen over that period, the toy expected positive exposure is ${m(ee)}. Positive shocks create exposure even when current margin is complete.`,note:'The selected category only changes the MPOR rule. A securities financing transaction is in CVA scope only if the required fair-value and materiality conditions are met.'};}});
 L.push({id:'wrong-way',name:'Wrong-way risk',stage:'01 · Exposure and valuation',title:'What if exposure rises when credit quality worsens?',intro:'Wrong-way risk connects what you may be owed with the chance of not being paid. Treating the two as independent can miss this link.',chart:'Default-weighted exposure in two future states',inputs:[slider('low','Exposure in calm state',0,50,1,5),slider('high','Exposure in stressed state',0,50,1,25),slider('pd','Average market-implied default probability',0,20,.5,5,'%'),slider('dependence','Credit/exposure alignment',-100,100,5,60,'%'),slider('lgd','Loss given default',20,80,5,60,'%')],challenge:'Keep average exposure and average default probability fixed, then reverse their alignment.',formula:'Joint expected loss = ½ × LGD × (Elow × PDlow + Ehigh × PDhigh)\nIndependent approximation = LGD × average(E) × average(PD)',key:'PDlow = PD × (1 − alignment), PDhigh = PD × (1 + alignment). The two states have equal probability.',simpleTitle:'The size of the claim can grow just as repayment becomes doubtful',simple:'A counterparty’s business may be exposed to the same market that drives your derivative receivable. When exposure and default likelihood rise together, averaging each separately loses important information.',scope:'A two-state, one-period risk-neutral teaching distribution without discounting. The alignment is not a Pearson correlation or a prescribed PRA parameter. Both state probabilities remain between zero and one over the controls.',pages:[[404,'5.6(3) · exposure / credit dependence']],compute(s){const p=s.pd/100,d=s.dependence/100,pl=p*(1-d),ph=p*(1+d),a=.5*s.low*pl*s.lgd/100,b=.5*s.high*ph*s.lgd/100,joint=a+b,ind=(s.low+s.high)/2*p*s.lgd/100;return {stats:[['Joint expected loss',m(joint)],['Independent estimate',m(ind)],['Dependence effect',m(joint-ind)]],bars:bars(['Calm contribution','Stress contribution','Joint loss','Independent loss'],[a,b,joint,ind]),headers:['State','Probability','Exposure','Conditional default probability','Loss contribution'],rows:[['Calm','50%',m(s.low),pct(pl),m(a)],['Stressed','50%',m(s.high),pct(ph),m(b)],['Combined','100%','Average '+m((s.low+s.high)/2),'Average '+pct(p),m(joint)]],explanation:`The joint expected loss is ${m(joint)}, compared with ${m(ind)} if exposure and default probability were independent. The difference of ${m(joint-ind)} comes entirely from how those two quantities line up across states.`,note:'Positive alignment is wrong-way risk only when the stressed-state exposure is higher; the controls let you test the opposite case too.'};}});
 L.push({id:'credit-curve',name:'Market-implied credit curves',stage:'01 · Exposure and valuation',title:'A spread curve connects today’s price to future default',intro:'Regulatory CVA uses market-implied default probabilities and market-consensus LGD. Historical default frequencies alone are not the prescribed valuation input.',chart:'Survival probability across time',inputs:[slider('short','Spread during years 0–2',0,1000,10,100,'bps'),slider('long','Spread after year 2',0,1000,10,250,'bps'),slider('lgd','Consistent market LGD',20,80,5,60,'%')],challenge:'Increase only the later spread. Why are the first two years unchanged in this teaching curve?',formula:'Toy segment hazard λ = spread / LGD\nSurvival(t) = exp(−λshort × min(t,2) − λlong × max(t−2,0))',key:'This piecewise-hazard construction illustrates term structure; it is not a bootstrapping algorithm for quoted CDS tenors.',simpleTitle:'Different maturities tell different credit stories',simple:'A counterparty can look stable in the near term but face uncertainty several years ahead. The timing of possible default matters when your exposure also changes over time.',scope:'Two flat hazard segments derived with a spread/LGD approximation. In practice a market curve is calibrated to observable instruments using the appropriate pricing conventions and consistent LGD.',pages:[[405,'5.7–5.8 · spreads, proxies and LGD']],notes:[['Missing quoted counterparty spreads','Proxy methodologies must distinguish at least credit quality, industry and region. A single-reference-name proxy needs justification to the PRA. Where suitable observed spreads are unavailable, an own assessment is possible under the rule, but resulting spreads cannot rely solely on historical default probabilities.'],['LGD consistency','Normally use the same market-consensus LGD used to infer risk-neutral default probability from spreads. Differences in transaction seniority require the specified adjustment. Collateral does not change derivative exposure seniority.']],compute(s){const surv=t=>Math.exp(-(s.short*Math.min(t,2)+s.long*Math.max(0,t-2))/10000/(s.lgd/100)),times=[1,2,3,5,10];return {stats:[['Two-year PD',pct(1-surv(2))],['Ten-year PD',pct(1-surv(10))],['Curve segments','2']],series:[{name:'Survival probability (%)',color:green,data:Array.from({length:101},(_,i)=>[i/10,100*surv(i/10)])}],y:[0,100],xlabel:'Years',headers:['Horizon','Survival probability','Cumulative default probability'],rows:times.map(t=>[t+' years',pct(surv(t)),pct(1-surv(t))]),explanation:`The two-year default probability is ${pct(1-surv(2))}, rising to ${pct(1-surv(10))} over ten years. Moving the later spread changes the later hazard segment. LGD and inferred probabilities must be calibrated consistently.`,note:'Market-implied probabilities are valuation inputs; they are not simply forecasts of observed default frequencies.'};}});
 L.push({id:'sensitivities',name:'Measuring delta and vega',stage:'02 · Sensitivities and hedges',title:'Revalue first, then divide by the bump',intro:'SA-CVA sensitivities come from changes in aggregate regulatory CVA and eligible hedge value under prescribed factor shifts.',chart:'Base and bumped regulatory CVA',inputs:[select('kind','Factor shift',[['credit','Counterparty spread · +1 bp'],['fx','FX spot · +1% relative'],['vega','Exposure volatility · +1% relative']],'credit'),slider('exposure','Base exposure scale',0,100,1,20),slider('spread','Counterparty spread',10,1000,10,150,'bps'),slider('vol','Exposure volatility',5,60,1,20,'%')],challenge:'Switch from a credit bump to a volatility bump. Does 1% relative mean adding one percentage point?',formula:'s = (bumped value − base value) / bump size\nRate / spread delta: bump = 0.0001\nSpot delta / vega: relative bump = 0.01',key:'A 1% relative shift to 20% volatility gives 20.2%, not 21%. Apply volatility shifts to exposure-path generation and option pricing as required.',simpleTitle:'CVA can have vega even without an option trade',simple:'Future positive exposure involves taking a positive part, so changes in market volatility can change expected exposure even for a portfolio of linear derivatives. The PRA requires vega sensitivities whether or not the portfolio contains options.',scope:'The CVA value model from the first lesson, with exposure scaled linearly by volatility and FX in this illustration. FX and volatility effects are stylised; an actual model must regenerate and reprice the appropriate risk-factor paths and any options.',pages:[[409,'5.18–5.19 · shifts and vega'],[412,'5.25 · relative volatility shifts'],[413,'5.26 · FX sensitivities'],[415,'5.27 · spread shifts']],compute(s){const exposure=s.exposure*s.vol/20,base=M.value({exposure,spread:s.spread,lgd:60,years:5,rate:3}).value,bump=s.kind==='credit'?.0001:.01,shifted=M.value({exposure:exposure*(s.kind==='credit'?1:1.01),spread:s.spread+(s.kind==='credit'?1:0),lgd:60,years:5,rate:3}).value,sens=(shifted-base)/bump;return {stats:[['Base CVA',m(base)],['Bump P&L',m(shifted-base)],['Sensitivity',m(sens)]],bars:bars(['Base CVA','Bumped CVA'],[base,shifted]),headers:['Step','Value','Meaning'],rows:[['Base CVA',m(base),'Loss-positive regulatory valuation'],['Bump',s.kind==='credit'?'+1 basis point':'+1% relative',s.kind==='vega'?s.vol+'% → '+(s.vol*1.01).toFixed(2)+'% volatility':'Specified factor shift'],['Bumped CVA',m(shifted),'Revalue at bumped inputs'],['Change',m(shifted-base),'Bumped minus base'],['Sensitivity',m(sens),'Change / '+bump]],explanation:`The CVA change is ${m(shifted-base)}. Dividing by ${bump} gives a sensitivity of ${m(sens)} per unit of the relevant shift. ${s.kind==='vega'?'Volatility affects the synthetic future exposure even though this example has no explicit option payoff.':''}`,note:'These are unweighted sensitivities. Risk weights and the CVA-minus-hedge convention enter the following lessons.'};}});
 L.push({id:'hedging',name:'Hedges and disallowance',stage:'02 · Sensitivities and hedges',title:'A matching hedge still leaves a prescribed charge',intro:'CVA is recorded as a positive loss. A hedge whose value rises under the same shock offsets that loss, so SA-CVA subtracts hedge sensitivity.',chart:'Capital as hedge size changes',inputs:[slider('cva','CVA sensitivity',0,200,5,100),slider('hedge','Eligible hedge sensitivity',-100,300,5,100),slider('rw','Illustrative risk weight',1,100,1,5,'%'),select('eligible','Hedge eligibility',[['yes','Meets SA-CVA hedge conditions'],['no','Not an eligible CVA hedge']],'yes')],challenge:'Match the hedge sensitivity exactly to CVA sensitivity. Then overhedge. Where does the charge go?',formula:'WS = RW × (sCVA − sHedge)\nOne-factor K = √[WS² + 0.01 × (RW × sHedge)²]',key:'R = 0.01 is inside the square root. An exact one-factor match leaves 10% of the absolute weighted hedge sensitivity, not 1%.',simpleTitle:'Price-risk neutral is not zero regulatory capital',simple:'The hedge removes net sensitivity, but the prescribed hedge-disallowance term remains. Taking more hedge than the exposure reverses the net position and can increase the charge again.',scope:'One factor and one bucket. The weight slider is an illustrative input, not permission to choose a regulatory weight. The six risk-class lessons use prescribed weights. Ineligible hedges are excluded from this CVA calculation.',pages:[[395,'Eligible SA-CVA hedge definition'],[398,'3.4–3.5 · hedge allocation'],[410,'5.22–5.24 · subtraction and disallowance']],notes:[['Eligible means more than economically helpful','A hedge must mitigate counterparty-spread or exposure variability, cannot be split into several effective transactions, and must meet the stated market-risk IMA eligibility condition. A credit-spread delta hedge is assigned wholly to either counterparty or reference spread risk.'],['Market-risk allocation','Eligible external CVA hedges are excluded from market-risk capital; ineligible external hedges remain in the trading-book market-risk calculation. Internal hedges subject to curvature, DRC or RRAO need the exact external-offset condition in 3.5.']],compute(s){const h=s.eligible==='yes'?s.hedge:0,b=M.bucket([s.cva],[h],[s.rw/100],1),curve=Array.from({length:81},(_,i)=>{const hedge=-100+i*5;return[hedge,M.bucket([s.cva],[s.eligible==='yes'?hedge:0],[s.rw/100],1).k]});return {stats:[['Capital',m(b.k)],['Net weighted sensitivity',m(b.net[0])],['Hedge term (squared)',n(b.disallowance)]],series:[{name:'One-factor capital (£m)',data:curve,color:green}],xlabel:'Hedge sensitivity (£m per unit shift)',headers:['Step','Result','Meaning'],rows:[['Weighted CVA',m(b.cv[0]),'RW × CVA sensitivity'],['Weighted eligible hedge',m(b.hd[0]),'RW × accepted hedge sensitivity'],['Net weighted sensitivity',m(b.net[0]),'CVA minus hedge'],['Net squared term',n(b.market)+' £m²','Net market exposure'],['Hedge-disallowance term',n(b.disallowance)+' £m²','0.01 × weighted hedge²'],['Capital',m(b.k),'Square root of both squared terms']],explanation:`Capital is ${m(b.k)}. ${b.net[0]===0&&h!==0?'Net sensitivity is zero, but the hedge-disallowance charge remains.':s.eligible==='no'?'The proposed hedge is not included; its separate market-risk treatment still matters.':'Both remaining exposure and the hedge term contribute under the square root.'}`,note:'Negative hedge sensitivity reinforces a positive CVA sensitivity under the loss-positive convention.'};}});
})();
